import{z as p,x as A,o as r,c as B,q as E,j as n,D as o,d as l,s,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"rollout 引擎与权重同步","description":"","frontmatter":{"title":"rollout 引擎与权重同步","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rollout-weight-sync.md","filePath":"llm/rollout-weight-sync.md","lastUpdated":1791063341000}'),d={name:"llm/rollout-weight-sync.md"};function m(h,a,u,D,C,g){const t=A("Mermaid");return r(),B("div",null,[a[2]||(a[2]=E('<h1 id="rollout-引擎与权重同步" tabindex="-1">rollout 引擎与权重同步 <a class="header-anchor" href="#rollout-引擎与权重同步" aria-label="Permalink to &quot;rollout 引擎与权重同步&quot;">​</a></h1><div class="epigraph"><p>生成用推理引擎、训练用 Megatron，中间那条权重边的延迟与一致性，决定 logprob 还能不能当 π_old。</p><footer>—— 对照 HybridFlow 的重切分、vLLM / SGLang 作为 rollouter、OpenRLHF 与 verl 的广播与 sleep 模式</footer></div><p><a href="/llm/off-policy-correction">上一课</a>要求每条轨迹有可信的 \\(\\log\\pi_{\\mathrm{beh}}\\)。缺口落到系统：<strong>推理引擎里的权重是不是 learner 刚推送的那一份，精度与模板是否一致。</strong> 异步架构课写时序契约；本课写同步边上的工程：广播、sleep 共置、重算。算法仍是 <a href="/llm/ppo-llm">PPO</a> / <a href="/llm/grpo">GRPO</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>训练布局（FSDP / Megatron 切分）与生成布局（TP + paged KV）不同。每次更新后要把 \\(\\theta\\) 变成生成引擎可加载的副本。共置 sleep：同一组 GPU 时分复用，权重切分转换，延迟低、实现重。分置：learner 训练、rollouter 常驻，NCCL / 参数服务器广播，生成可持续，但推送瞬间版本跃迁。推送频率低，staleness 升；频率高，气泡升。</p><p>失败模式：引擎仍用旧权生成，却把当前 \\(\\theta\\) 的 logprob 当成 \\(\\pi_{\\mathrm{beh}}\\)——IS 全错。或生成用 chat 模板 A，训练前向用模板 B，奖励打在另一字符串上。</p><h3 id="缓存的-logprob-属于哪一版" tabindex="-1">缓存的 logprob 属于哪一版 <a class="header-anchor" href="#缓存的-logprob-属于哪一版" aria-label="Permalink to &quot;缓存的 logprob 属于哪一版&quot;">​</a></h3><p>生成时应在<strong>同一次前向</strong>里记下 \\(\\log\\pi_{\\mathrm{beh}}\\)，与发出的 token 对齐，含温度、top-\\(p\\) 是否作用于采样但不作用于要存储的裸 logprob。存储裸 \\(\\log\\pi\\)（softmax 前的分布对数），采样约束另记。训练重算必须关 dropout、对齐精度。</p><p><span class="marginnote">LoRA 只同步 A/B 矩阵时，基座必须双方锁定同一份。漏同步一份 adapter，就是静默 off-policy。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>最小协议：<code>sync_id</code> 单调递增；rollouter 加载成功才接受新请求；正在解码的序列要么跑完旧版，要么中断重算 KV。Learner 在 <code>sync_id</code> 写入样本元数据。评测路径与训练生成共用同一引擎配置。重切分（3D-HybridEngine）把训练切分转成推理切分，避免 CPU 落盘。</p>',11)),(r(),n(i,null,{default:o(()=>[s(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20LR%0A%20%20L%5B%22Learner%20%CE%B8%22%5D%20--%3E%20S%5B%22sync_id%20%E5%B9%BF%E6%92%AD%20%2F%20%E9%87%8D%E5%88%87%E5%88%86%22%5D%0A%20%20S%20--%3E%20R%5B%22Rollouter%20%E5%8A%A0%E8%BD%BD%22%5D%0A%20%20R%20--%3E%20Y%5B%22%E9%87%87%E6%A0%B7%20y%20%2B%20log%CF%80_beh%22%5D%0A%20%20Y%20--%3E%20Q%5B%22%E5%B8%A6%20sync_id%20%E5%85%A5%E9%98%9F%22%5D%0A%20%20Q%20--%3E%20L%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[l("与奖励模型同步：RM 冻结则少一条边；RM 迭代时要第二份 "),e("code",null,"sync_id"),l("，否则策略与裁判版本错位，像在优化旧口味。")],-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：策略在按「本届评委」的打分调口味，评委却悄悄换成了上一届。训练信号方向没错，但优化的目标函数已经是旧的——RM 版本错位不会报错、不会发散得很明显，只会让策略学出一套「讨好前任评委」的行为。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"权重边的延迟进入 staleness \\(\\eta\\)。数学上 \\(\\eta\\) 已在上一课定义；本课决定 \\(\\eta\\) 的物理下限：广播 70B 权重要多少毫秒。部分同步（只推 embedding）会造成层间版本撕裂，比整网落后一拍更难校正。要么全量原子换，要么明确冻结哪些层。",-1)),a[7]||(a[7]=e("p",null,"一条更新后的 \\(\\theta\\) 怎样到达生成引擎，以及推送频率怎样换走两种代价：",-1)),(r(),n(i,null,{default:o(()=>[s(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%CE%B8%20%E6%9B%B4%E6%96%B0%E5%AE%8C%E6%88%90%22%5D%20--%3E%20C%7B%22%E9%80%89%E5%93%AA%E6%9D%A1%E5%90%8C%E6%AD%A5%E8%B7%AF%E7%BA%BF%22%7D%0A%20%20C%20--%3E%7C%22%E5%85%B1%E7%BD%AE%22%7C%20R%5B%22%E5%90%8C%E5%8D%A1%E9%87%8D%E5%88%87%E5%88%86%EF%BC%9A%E8%AE%AD%E7%BB%83%E5%B8%83%E5%B1%80%E8%BD%AC%E6%8E%A8%E7%90%86%E5%B8%83%E5%B1%80%22%5D%0A%20%20C%20--%3E%7C%22%E5%88%86%E7%BD%AE%22%7C%20B%5B%22NCCL%20%2F%20%E5%8F%82%E6%95%B0%E6%9C%8D%E5%8A%A1%E5%99%A8%E5%B9%BF%E6%92%AD%22%5D%0A%20%20R%20--%3E%20A%5B%22%E5%8E%9F%E5%AD%90%E6%8D%A2%E6%9D%83%20%2B%20%E4%BD%BF%E8%83%BD%20CUDA%20graph%20%E7%BC%93%E5%AD%98%E5%A4%B1%E6%95%88%22%5D%0A%20%20B%20--%3E%20A%0A%20%20A%20--%3E%20V%5B%22rollouter%20%E6%A0%A1%E9%AA%8C%E5%93%88%E5%B8%8C%EF%BC%8C%E5%AE%A3%E5%B8%83%E6%96%B0%20sync_id%20%E7%94%9F%E6%95%88%22%5D%0A%20%20V%20--%3E%20F%5B%22%E6%8E%A8%E5%BE%97%E9%A2%91%E7%B9%81%EF%BC%9Astaleness%20%E4%BD%8E%EF%BC%8C%E8%A7%A3%E7%A0%81%E5%86%92%E6%B0%94%E6%B3%A1%22%5D%0A%20%20V%20--%3E%20S%5B%22%E6%8E%A8%E5%BE%97%E7%A8%80%E7%96%8F%EF%BC%9A%E8%A7%A3%E7%A0%81%E6%B5%81%E7%95%85%EF%BC%8C%E8%BD%A8%E8%BF%B9%E7%89%88%E6%9C%AC%E6%9B%B4%E6%97%A7%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=E('<p><span class="marginnote">数字感受一下物理下限：70B 权重按 fp16 存约 140 GB。走 PCIe 4.0（约 32 GB/s）单趟要 140 ÷ 32 ≈ 4 秒多，一步预算里相当扎眼；走 NVLink 级互连（数百 GB/s）能压到亚秒。所以「权重边打不打得快」首先由互连拓扑决定，其次才是软件实现。</span></p><p><span class="marginnote">「staleness（陈旧度）」指生成这条轨迹所用的权重，比 learner 当前的权重落后几个版本。初学者容易以为落后一拍无关紧要——实际上 PPO 的重要性比率随版本差指数级失真，落后 2 版的轨迹给梯度贡献的信息可能已经接近噪声，这也是为什么要用 sync_id 把它管起来。</span></p><p><span class="marginnote">CUDA graph / 编译缓存按形状绑定。换权后必须使缓存失效。旧 graph 跑新权是未定义行为。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>小模型共置同步更简单，不必上参数服务器。长链推理才值得分置。MoE 还要同步路由专家，漏专家比漏一层更致命。同步完成应以 rollouter 的校验哈希为准，不要信发送端「已推送」。下一课采样温度：即使权重一致，解码随机性仍改变 \\(\\pi_{\\mathrm{beh}}\\) 的定义——温度是策略的一部分，不是 UI。</p><p>sync_id 要以 rollouter 加载成功为准；模板、LoRA、MoE 专家漏同步会让比率在版本号正确时仍然全错。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>训练与生成之间的权重同步必须原子、带 sync_id，logπ_beh 与该版对齐。</li><li>共置重切分延迟低；分置广播吞吐高、staleness 要配额。</li><li>模板、LoRA、MoE 专家漏同步 = 静默错误 IS。</li><li>RM 若迭代，裁判也要版本号。</li><li>出处：Sheng 等 HybridFlow；OpenRLHF / verl / slime 的 rollouter 实践。</li></ul>',8))])}const b=p(d,[["render",m]]);export{_ as __pageData,b as default};
